using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageRequirementTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
        using MessagePack;

        namespace Receipts.Sample
        {
            [GeneratedMessagePackResolver]
            internal partial class MyResolver
            {
            }

            public enum Color { Red, Green }

            [MessagePackObject]
            public class IntKeyed
            {
                [Key(0)]
                public int Value { get; set; }

                [Key(1)]
                public Color Color { get; set; }
            }

            [MessagePackObject]
            public class StringKeyed
            {
                [Key("name")]
                public string Name { get; set; }
            }

            [Union(0, typeof(UnionCase))]
            public interface IUnionBase
            {
            }

            [MessagePackObject]
            public class UnionCase : IUnionBase
            {
                [Key(0)]
                public int X { get; set; }
            }
        }
        """;

    [Fact]
    public async Task GeneratedFormatters_AreDecoratedWithExcludeFromCodeCoverage()
    {
        Compilation output = await RunGeneratorAsync(Source);

        Diagnostic[] errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToArray();
        Assert.True(errors.Length == 0, string.Join(Environment.NewLine, errors.Select(e => e.ToString())));

        List<string> missing = FindUndecoratedFormatters(output, out int formatterCount);
        Assert.True(formatterCount > 0, "Expected the generator to emit at least one formatter.");
        Assert.Empty(missing);
    }

    [Fact]
    public async Task GeneratedResolver_IsDecoratedWithExcludeFromCodeCoverage()
    {
        Compilation output = await RunGeneratorAsync(Source);

        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("Receipts.Sample.MyResolver");
        Assert.NotNull(resolver);
        Assert.True(HasExcludeFromCodeCoverage(resolver!), "Generated resolver lacks [ExcludeFromCodeCoverage].");
    }

    private static async Task<Compilation> RunGeneratorAsync(string source, params string[] preprocessorSymbols)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3, preprocessorSymbols: preprocessorSymbols);
        ImmutableArray<MetadataReference> frameworkReferences = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> references = frameworkReferences.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> _);
        return output;
    }

    private static List<string> FindUndecoratedFormatters(Compilation output, out int formatterCount)
    {
        List<string> missing = new List<string>();
        formatterCount = 0;
        foreach (SyntaxTree tree in output.SyntaxTrees.Skip(1))
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax declaration in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(declaration) is not INamedTypeSymbol symbol)
                {
                    continue;
                }

                if (!symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter"))
                {
                    continue;
                }

                formatterCount++;
                if (!HasExcludeFromCodeCoverage(symbol))
                {
                    missing.Add(symbol.ToDisplayString());
                }
            }
        }

        return missing;
    }

    private static bool HasExcludeFromCodeCoverage(INamedTypeSymbol symbol)
    {
        return symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName);
    }
}

