                [Key(0)]
                public int Value { get; set; }
            }
        }
        """;

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task GeneratedFormatters_AreDecorated_WhenTargetSymbolDefined(string targetSymbol)
    {
        ImmutableArray<MetadataReference> netStandardReferences = await ReferenceAssemblies.NetStandard.NetStandard20.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation probe = CSharpCompilation.Create("Probe", references: netStandardReferences);
        Assert.NotNull(probe.GetTypeByMetadataName(AttributeName));

        Compilation output = await RunGeneratorAsync(Source, targetSymbol);

        List<string> missing = FindUndecoratedFormatters(output, out int formatterCount);
        Assert.True(formatterCount > 0, "Expected the generator to emit at least one formatter.");
        Assert.Empty(missing);
    }

    [Fact]
    public async Task UserResolverAlreadyExcludedFromCoverage_StillCompiles()
    {
        Compilation output = await RunGeneratorAsync(SourceWithUserExcludedResolver);

        Diagnostic[] errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToArray();
        Assert.True(errors.Length == 0, string.Join(Environment.NewLine, errors.Select(e => e.ToString())));
    }

