        IEnumerable<MetadataReference> references = frameworkReferences.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsGapAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> _);
        return output;
    }

    private static List<string> FindUndecoratedFormatters(Compilation output, out int formatterCount)
    {
        List<string> missing = new List<string>();
        formatterCount = 0;
        foreach (SyntaxTree tree in output.SyntaxTrees.Skip(1))
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax declaration in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(declaration) is not INamedTypeSymbol symbol)
                {
                    continue;
                }

                if (!symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter"))
                {
                    continue;
                }

                formatterCount++;
                if (!symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName))
                {
                    missing.Add(symbol.ToDisplayString());
                }
            }
        }

        return missing;
    }
}
